import React from 'react';
import { Link as RouterLink } from 'react-router-dom';
import { ArrowRight } from 'lucide-react';

import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  CardFooter,
} from "../ui/card";

import { Button } from "../ui/button";

const ProcessCard = ({ process }) => {
  // Generate a title: use process.title if available, then general_description, then ID
  let displayTitle = 'Untitled Process';
  if (process.title) {
    displayTitle = process.title;
  } else if (process.general_description) {
    const words = process.general_description.split(' ');
    displayTitle = words.slice(0, 7).join(' '); // Show a bit more for title
    if (words.length > 7) displayTitle += '...';
  } else if (process.id) {
    displayTitle = `Process ID: ${process.id.substring(0, 8)}...`;
  }

  const displayDescription = process.general_description || 'No detailed description available.';
  const truncatedDescription = displayDescription.length > 150 
    ? displayDescription.substring(0, 150) + '...' 
    : displayDescription;

  return (
    <Card className="h-full flex flex-col hover:shadow-lg transition-shadow duration-300">
      <CardHeader>
        <CardTitle className="text-xl">{displayTitle}</CardTitle>
        <CardDescription className="line-clamp-2">
          {truncatedDescription}
        </CardDescription>
      </CardHeader>
      <CardContent className="flex-grow">
        <div className="space-y-2 text-sm text-muted-foreground">
          {process.process_steps && process.process_steps.length > 0 && (
            <div>
              <strong className="text-foreground">Steps:</strong>{' '}
              {process.process_steps.length} defined
            </div>
          )}
          {process.roles_responsibilities && process.roles_responsibilities.length > 0 && (
            <div>
              <strong className="text-foreground">Roles:</strong>{' '}
              {process.roles_responsibilities.length} assigned
            </div>
          )}
        </div>
      </CardContent>
      <CardFooter className="pt-6">
        <Button
          asChild
          variant="outline"
          className="w-full group"
        >
          <RouterLink to={`/process/${process.id}`}>
            View Details
            <ArrowRight className="ml-2 h-4 w-4 group-hover:translate-x-1 transition-transform" />
          </RouterLink>
        </Button>
      </CardFooter>
    </Card>
  );
};

export default ProcessCard;
